// The hosted independent MCP adapter (mcp/server.mjs --remote, docs/network/hosted-mcp.md) as ONE file for the measured
// control guest (/opt/metal/mcp-server.bundle.mjs, started by gsup.mjs for a bound config with an mcp member). The same
// pattern as scripts/build-metal-lease-gas.mjs: exact inputs recorded in a manifest; --check refuses a stale one. Not
// minified, so the bytes inside the measurement stay reviewable.
import { build } from "esbuild";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const entry = "mcp/server.mjs", output = path.join(root, "metal/guest/mcp-server.bundle.mjs");
// the bundle ENTRY is the argv-guarded wrapper (metal/guest/mcp-server-entry.mjs) that calls mcp/server.mjs's main
const bundleEntry = "metal/guest/mcp-server-entry.mjs";
// Files the bundled code reads beside itself at run time (new URL(<relative>, import.meta.url)), as IMAGE paths -> repository
// source. The bundle runs as /opt/metal/mcp-server.bundle.mjs, so "./fixtures/tpm-roots.pem" (relay/vbs-policy.mjs, Windows VBS
// hosts) is opt/metal/fixtures/tpm-roots.pem and "../contracts/deployments/contract-pins-base.json" (network/native-host-policy.mjs,
// the management tools) is opt/contracts/deployments/contract-pins-base.json. The image builders install them with these hashes.
export const BUNDLE_DIR = "opt/metal";
export const RUNTIME_FILES = Object.freeze({ "opt/metal/fixtures/tpm-roots.pem": "relay/fixtures/tpm-roots.pem",
  "opt/contracts/deployments/contract-pins-base.json": "contracts/deployments/contract-pins-base.json" });
const args = process.argv.slice(2);
const outIdx = args.indexOf("--out");
if (args.some((a, i) => !(a === "--check" || a === "--out" || (outIdx >= 0 && i === outIdx + 1)))) throw new Error("usage: build-mcp-guest-bundle.mjs [--check] [--out DIR]");
const result = await build({
  absWorkingDir: root, entryPoints: [bundleEntry], outfile: output,
  platform: "node", format: "esm", target: "node20", bundle: true, minify: false, write: false, metafile: true, legalComments: "none", preserveSymlinks: true,
  // esm output of cjs dependencies needs a require for node builtins
  banner: { js: "// Generated by scripts/build-mcp-guest-bundle.mjs from mcp/server.mjs; do not edit.\nimport { createRequire as __mcpCreateRequire } from 'node:module'; const require = __mcpCreateRequire(import.meta.url);" },
});
const bytes = Buffer.from(result.outputFiles[0].contents);
const sha = (b) => createHash("sha256").update(b).digest("hex");
// preserveSymlinks keeps every input at its path in this tree (a symlinked node_modules included), so the manifest names
// each nested dependency copy apart (node_modules/ox and relay/node_modules/ox differ)
const inputs = {};
for (const rel of Object.keys(result.metafile.inputs).sort()) {
  if (rel.startsWith("..") || path.isAbsolute(rel)) throw new Error(`bundle input outside the tree: ${rel}`);
  inputs[rel] = sha(await fs.readFile(path.resolve(root, rel)));
}
for (const must of [entry, bundleEntry, "network/host-services/argv-guard.mjs"])
  if (!inputs[must]) throw new Error(`the bundle does not carry ${must}`);
// every relative file the bundled code resolves against its own URL must be a declared runtime file (none silently missing)
const text = bytes.toString("utf8");
for (const m of text.matchAll(/new URL\(\s*["'](\.{1,2}\/[^"']+)["']\s*,\s*import\.meta\.url\s*\)/g)) {
  const at = path.posix.normalize(`${BUNDLE_DIR}/${m[1]}`);
  if (!RUNTIME_FILES[at]) throw new Error(`the bundle reads ${m[1]} beside itself (${at}), which is not a declared runtime file`);
}
const runtimeFiles = {};
for (const [at, src] of Object.entries(RUNTIME_FILES)) runtimeFiles[at] = { source: src, sha256: sha(await fs.readFile(path.join(root, src))) };
const manifest = JSON.stringify({ bundle: "metal/guest/mcp-server.bundle.mjs", entry, bundleEntry, sha256: sha(bytes), bytes: bytes.length, inputs, runtimeFiles }, null, 2) + "\n";
if (args.includes("--check")) {
  if (!bytes.equals(await fs.readFile(output))) throw new Error("the hosted MCP guest bundle is stale; run node scripts/build-mcp-guest-bundle.mjs");
  if (manifest !== await fs.readFile(output + ".manifest.json", "utf8")) throw new Error("the hosted MCP guest bundle manifest is stale");
} else {
  const dir = outIdx >= 0 ? path.resolve(args[outIdx + 1]) : path.dirname(output);
  await fs.mkdir(dir, { recursive: true });
  await fs.writeFile(path.join(dir, "mcp-server.bundle.mjs"), bytes);
  await fs.writeFile(path.join(dir, "mcp-server.bundle.mjs.manifest.json"), manifest);
}
console.log(`hosted MCP guest bundle: ${bytes.length} bytes, sha256:${sha(bytes)}, ${Object.keys(inputs).length} inputs, ${Object.keys(runtimeFiles).length} runtime file(s)${args.includes("--check") ? " (verified)" : ""}`);
